        for (int i = 0; i < 20; i++) {
            method.invoke(connection);
        }
        return null;
    });
    future.get(60, TimeUnit.SECONDS);
    assertThat(messageLatch.await(10, TimeUnit.SECONDS)).isTrue();
    exec.shutdownNow();
}

