    assertThat(out.get(0)).isEqualTo("foo/fiz.txt");
    assertThat(out.get(1)).isEqualTo("foo/buz.txt");
    assertThat(written.get()).isEqualTo("foo/buz.txt.writing");
    verify(session).rename("foo/buz.txt.writing", "foo/buz.txt");
}

