    assertThat(message.getPayload()).isSameAs(event2);
    message = outputChannel.receive(0);
    assertThat(message).isNotNull();
    assertThat(message.getPayload()).isSameAs(event3);
    message = outputChannel.receive(0);
    assertThat(message).isNull();
}

