    SimpleMessageListenerContainer container = new SimpleMessageListenerContainer();
    container.setConnectionFactory(connectionFactory);
    container.setAcknowledgeMode(AcknowledgeMode.MANUAL);
    DirectChannel channel = new DirectChannel();
    Channel rabbitChannel = mock();
    channel.subscribe(new MessageTransformingHandler(message -> {
        assertThat(message.getHeaders().get(AmqpHeaders.CHANNEL)).isSameAs(rabbitChannel);
        assertThat(message.getHeaders().get(AmqpHeaders.DELIVERY_TAG)).isEqualTo(123L);
        return MessageBuilder.fromMessage(message).setHeader(JsonHeaders.TYPE_ID, "foo").setHeader(JsonHeaders.CONTENT_TYPE_ID, "bar").setHeader(JsonHeaders.KEY_TYPE_ID, "baz").build();
    }));
    RabbitTemplate rabbitTemplate = spy(new RabbitTemplate());
    rabbitTemplate.setMessageConverter(new JacksonJsonMessageConverter("*"));
    CountDownLatch sendLatch = new CountDownLatch(1);
    Mockito.doAnswer(invocation -> {
        org.springframework.amqp.core.Message message = invocation.getArgument(2);
        Map<String, Object> headers = message.getMessageProperties().getHeaders();
        assertThat(headers).doesNotContainKeys(JsonHeaders.CONTENT_TYPE_ID.replaceFirst(JsonHeaders.PREFIX, ""), JsonHeaders.KEY_TYPE_ID.replaceFirst(JsonHeaders.PREFIX, ""), JsonHeaders.TYPE_ID, JsonHeaders.KEY_TYPE_ID, JsonHeaders.CONTENT_TYPE_ID).containsEntry(JsonHeaders.TYPE_ID.replaceFirst(JsonHeaders.PREFIX, ""), InboundEndpointTests.Foo.class.getName());
        sendLatch.countDown();
        return null;
    }).when(rabbitTemplate).send(anyString(), anyString(), any(org.springframework.amqp.core.Message.class), isNull());
    AmqpInboundGateway gateway = new AmqpInboundGateway((MessageListenerContainer) container, rabbitTemplate);
