        when(ftpClient.login("kermit", "frog")).thenReturn(true);
        when(ftpClient.changeWorkingDirectory(Mockito.anyString())).thenReturn(true);
        when(ftpClient.printWorkingDirectory()).thenReturn("remote-target-dir");
