    assertThat(theEvent.get(0)).isNotNull();
    assertThat(theEvent.get(0)).isInstanceOf(TcpConnectionExceptionEvent.class);
    assertThat(theEvent.get(0).toString().endsWith("[factory=foo, connectionId=" + conn.getConnectionId() + "]")).isTrue();
    assertThat(theEvent.get(0)).extracting("cause").asInstanceOf(InstanceOfAssertFactories.THROWABLE).hasStackTraceContaining("RuntimeException: foo").hasStackTraceContaining("failedMessage=GenericMessage [payload=bar");
