public void testObtainConnectionIds(AbstractServerConnectionFactory serverFactory) throws Exception {
    final List<IpIntegrationEvent> events = Collections.synchronizedList(new ArrayList<>());
    int expectedEvents = serverFactory instanceof TcpNetServerConnectionFactory ? // Listening, + OPEN, CLOSE, EXCEPTION for each side
    7 : // Listening, + OPEN, CLOSE (but we *might* get exceptions, depending on timing).
    5;
    final CountDownLatch serverListeningLatch = new CountDownLatch(1);
    final CountDownLatch eventLatch = new CountDownLatch(expectedEvents);
    ApplicationEventPublisher publisher = event -> {
        LogFactory.getLog(this.getClass()).trace("Received: " + event);
        events.add((IpIntegrationEvent) event);
        if (event instanceof TcpConnectionServerListeningEvent) {
            serverListeningLatch.countDown();
        }
        eventLatch.countDown();
    };
    serverFactory.setBeanName("serverFactory");
    serverFactory.setApplicationEventPublisher(publisher);
    serverFactory.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    serverFactory = spy(serverFactory);
    final CountDownLatch serverConnectionInitLatch = new CountDownLatch(1);
    doAnswer(invocation -> {
        Object result = invocation.callRealMethod();
        serverConnectionInitLatch.countDown();
        return result;
    }).when(serverFactory).wrapConnection(any(TcpConnectionSupport.class));
    ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
    scheduler.setPoolSize(10);
    scheduler.afterPropertiesSet();
    serverFactory.setTaskScheduler(new SimpleAsyncTaskScheduler());
    serverFactory.afterPropertiesSet();
    TcpReceivingChannelAdapter adapter = new TcpReceivingChannelAdapter();
    adapter.setOutputChannel(new NullChannel());
    adapter.setConnectionFactory(serverFactory);
    adapter.start();
    assertThat(serverListeningLatch.await(10, TimeUnit.SECONDS)).as("Listening event not received").isTrue();
    assertThat(events.get(0)).isInstanceOf(TcpConnectionServerListeningEvent.class);
    assertThat(((TcpConnectionServerListeningEvent) events.get(0)).getPort()).isEqualTo(serverFactory.getPort());
    int port = serverFactory.getPort();
    TcpNetClientConnectionFactory clientFactory = new TcpNetClientConnectionFactory("localhost", port);
    clientFactory.registerListener(message -> {
    });
    clientFactory.setBeanName("clientFactory");
    clientFactory.setApplicationEventPublisher(publisher);
    clientFactory.start();
    TcpConnectionSupport client = clientFactory.getConnection();
    List<String> clients = clientFactory.getOpenConnectionIds();
    assertThat(clients).hasSize(1);
    assertThat(clients.contains(client.getConnectionId())).isTrue();
    assertThat(serverConnectionInitLatch.await(10, TimeUnit.SECONDS)).as("Server connection failed to register").isTrue();
    List<String> servers = serverFactory.getOpenConnectionIds();
    assertThat(servers).hasSize(1);
    assertThat(serverFactory.closeConnection(servers.get(0))).isTrue();
    servers = serverFactory.getOpenConnectionIds();
    assertThat(servers).isEmpty();
    await().atMost(Duration.ofSeconds(10)).until(() -> clientFactory.getOpenConnectionIds().isEmpty());
    clients = clientFactory.getOpenConnectionIds();
    assertThat(clients).isEmpty();
    assertThat(eventLatch.await(10, TimeUnit.SECONDS)).isTrue();
    assertThat(events.size()).as("Expected at least " + expectedEvents + " events; got: " + events.size() + " : " + events).isGreaterThanOrEqualTo(expectedEvents);
    FooEvent event = new FooEvent(client, "foo");
    client.publishEvent(event);
    assertThat(events.size()).as("Expected at least " + expectedEvents + " events; got: " + events.size() + " : " + events).isGreaterThanOrEqualTo(expectedEvents + 1);
    FooEvent wrongEvent = new FooEvent(mock(TcpConnectionSupport.class), "foo");
    assertThatIllegalArgumentException().isThrownBy(() -> client.publishEvent(wrongEvent)).withMessage("Can only publish events with this as the source");
    SocketAddress address = serverFactory.getServerSocketAddress();
    if (address instanceof InetSocketAddress inetAddress) {
        assertThat(inetAddress.getPort()).isEqualTo(port);
    }
    serverFactory.stop();
    scheduler.shutdown();
}

private void testRefreshShared(boolean closeOnRefresh, long interval) throws Exception {
    AbstractClientConnectionFactory factory1 = mock(AbstractClientConnectionFactory.class);
    AbstractClientConnectionFactory factory2 = mock(AbstractClientConnectionFactory.class);
    List<AbstractClientConnectionFactory> factories = new ArrayList<>();
    factories.add(factory1);
    factories.add(factory2);
    TcpConnectionSupport conn1 = makeMockConnection();
    doReturn("conn1").when(conn1).getConnectionId();
    TcpConnectionSupport conn2 = makeMockConnection();
    doReturn("conn2").when(conn2).getConnectionId();
    doThrow(new UncheckedIOException(new IOException("fail"))).when(factory1).getConnection();
    if (closeOnRefresh) {
        when(factory2.getConnection()).thenReturn(conn1, conn2);
    } else {
        when(factory2.getConnection()).thenReturn(conn1);
    }
    when(factory1.isActive()).thenReturn(true);
    when(factory2.isActive()).thenReturn(true);
    FailoverClientConnectionFactory failoverFactory = new FailoverClientConnectionFactory(factories);
    failoverFactory.setCloseOnRefresh(closeOnRefresh);
    failoverFactory.start();
    TcpConnectionSupport connection = failoverFactory.getConnection();
