    QueueChannel outputChannel = new QueueChannel();
    NotificationListeningMessageProducer adapter = new NotificationListeningMessageProducer();
    adapter.setServer(this.server);
    adapter.setObjectName(this.objectName);
    adapter.setOutputChannel(outputChannel);
    adapter.setBeanFactory(mock());
    adapter.afterPropertiesSet();
    adapter.start();
    adapter.onApplicationEvent(new ContextRefreshedEvent(mock()));
    this.numberHolder.publish("test");
    Message<?> message = outputChannel.receive(0);
    assertThat(message).isNotNull();
    assertThat(message.getPayload()).isInstanceOf(Notification.class);
    Notification notification = (Notification) message.getPayload();
    assertThat(notification.getMessage()).isEqualTo("test");
    assertThat(notification.getSource()).isEqualTo(objectName);
    assertThat(message.getHeaders()).doesNotContainKey(JmxHeaders.NOTIFICATION_HANDBACK);
}

@Test
public void notificationWithHandback() {
    QueueChannel outputChannel = new QueueChannel();
    NotificationListeningMessageProducer adapter = new NotificationListeningMessageProducer();
    adapter.setServer(this.server);
    adapter.setObjectName(this.objectName);
    adapter.setOutputChannel(outputChannel);
    Integer handback = 123;
    adapter.setHandback(handback);
    adapter.setBeanFactory(mock());
    adapter.afterPropertiesSet();
    adapter.start();
    adapter.onApplicationEvent(new ContextRefreshedEvent(mock()));
    this.numberHolder.publish("test");
    Message<?> message = outputChannel.receive(0);
    assertThat(message).isNotNull();
    assertThat(message.getPayload()).isInstanceOf(Notification.class);
    Notification notification = (Notification) message.getPayload();
    assertThat(notification.getMessage()).isEqualTo("test");
    assertThat(notification.getSource()).isEqualTo(objectName);
    assertThat(message.getHeaders()).containsEntry(JmxHeaders.NOTIFICATION_HANDBACK, handback);
}

@Test
public void notificationWithFilter() {
    QueueChannel outputChannel = new QueueChannel();
    NotificationListeningMessageProducer adapter = new NotificationListeningMessageProducer();
    adapter.setServer(this.server);
    adapter.setObjectName(this.objectName);
    adapter.setOutputChannel(outputChannel);
    adapter.setFilter(notification -> !notification.getMessage().equals("bad"));
    adapter.setBeanFactory(mock());
    adapter.afterPropertiesSet();
    adapter.start();
    adapter.onApplicationEvent(new ContextRefreshedEvent(mock()));
    this.numberHolder.publish("bad");
    Message<?> message = outputChannel.receive(0);
    assertThat(message).isNull();
    this.numberHolder.publish("okay");
    message = outputChannel.receive(0);
    assertThat(message).isNotNull();
    assertThat(message.getPayload()).isInstanceOf(Notification.class);
    Notification notification = (Notification) message.getPayload();
    assertThat(notification.getMessage()).isEqualTo("okay");
}

/**
 * In this test, the {@link JpaExecutor}'s poll method will be called without
 * specifying a 'query', 'namedQuery' or 'entityClass' property. This should
 * result in an {@link IllegalArgumentException}.
 */
@Test
public void testExecutePollWithNoEntityClassSpecified() {
    JpaExecutor jpaExecutor = new JpaExecutor(mock(EntityManager.class));
    jpaExecutor.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    jpaExecutor.afterPropertiesSet();
    assertThatIllegalStateException().isThrownBy(jpaExecutor::poll).withMessage("For the polling operation, one of " + "the following properties must be specified: " + "jpaQuery, nativeQuery, namedQuery or entityClass.");
}

@Test
public void testSetMultipleQueryTypes() {
    final JpaExecutor executor = new JpaExecutor(mock(EntityManager.class));
    executor.setJpaQuery("select s from Student s");
    assertThat(TestUtils.<String>getPropertyValue(executor, "jpaQuery")).isNotNull();
    assertThatIllegalArgumentException().isThrownBy(() -> executor.setNamedQuery("NamedQuery")).withMessage("Only one of the properties 'jpaQuery', 'nativeQuery', 'namedQuery' can be defined");
    assertThat(TestUtils.<Object>getPropertyValue(executor, "namedQuery")).isNull();
    assertThatIllegalArgumentException().isThrownBy(() -> executor.setNativeQuery("select * from Student")).withMessage("Only one of the properties 'jpaQuery', 'nativeQuery', 'namedQuery' can be defined");
    assertThat(TestUtils.<Object>getPropertyValue(executor, "nativeQuery")).isNull();
    final JpaExecutor executor2 = new JpaExecutor(mock(EntityManager.class));
    executor2.setNamedQuery("NamedQuery");
    assertThat(TestUtils.<String>getPropertyValue(executor2, "namedQuery")).isNotNull();
    assertThatIllegalArgumentException().isThrownBy(() -> executor2.setJpaQuery("select s from Student s")).withMessage("Only one of the properties 'jpaQuery', 'nativeQuery', 'namedQuery' can be defined");
    assertThat(TestUtils.<Object>getPropertyValue(executor2, "jpaQuery")).isNull();
}

