@Test
void testSyncMode() {
    MockProducer<Integer, String> mockProducer = new MockProducer<>(false, new MockPartitioner(), new IntegerSerializer(), new StringSerializer()) {

        @Override
        public void close(Duration timeout) {
            // To avoid non transactional closes.
        }
    };
    @SuppressWarnings("unchecked")
    ProducerFactory<Integer, String> pf = mock(ProducerFactory.class);
    given(pf.createProducer()).willReturn(mockProducer);
    Map<String, Object> props = new HashMap<>();
    props.put(ProducerConfig.DELIVERY_TIMEOUT_MS_CONFIG, 10);
    given(pf.getConfigurationProperties()).willReturn(props);
    KafkaTemplate<Integer, String> template = new KafkaTemplate<>(pf);
    KafkaProducerMessageHandler<Integer, String> handler = new KafkaProducerMessageHandler<>(template);
    handler.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    handler.afterPropertiesSet();
    handler.setSync(true);
    handler.setSendTimeout(10_000);
    handler.setTimeoutBuffer(200);
    handler.setTopicExpression(new LiteralExpression("foo"));
    ExecutorService executorService = Executors.newSingleThreadExecutor();
    executorService.submit(() -> {
        RuntimeException exception = new RuntimeException("Async Producer Mock exception");
        while (!mockProducer.errorNext(exception)) {
            Thread.sleep(100);
        }
        return null;
    });
    assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> handler.handleMessage(new GenericMessage<>("foo"))).withCauseInstanceOf(KafkaException.class).withRootCauseInstanceOf(RuntimeException.class).withStackTraceContaining("Async Producer Mock exception");
    handler.setSendTimeout(1);
    assertThatExceptionOfType(MessageTimeoutException.class).isThrownBy(() -> handler.handleMessage(new GenericMessage<>("foo"))).withCauseInstanceOf(TimeoutException.class).withStackTraceContaining("Timeout waiting for response from KafkaProducer");
    executorService.shutdown();
}

