    AtomicReference<String> txId = new AtomicReference<>();
    DefaultKafkaProducerFactory pf = new DefaultKafkaProducerFactory(Collections.emptyMap()) {

        @Override
        protected Producer createTransactionalProducer(String txIdPrefix) {
            txId.set(txIdPrefix);
            return producer;
        }
    };
