@Test
public void testExists() throws IOException {
    SftpClient sftpClient = mock(SftpClient.class);
    willReturn("/exist").given(sftpClient).canonicalPath("exist");
    willReturn("/notExist").given(sftpClient).canonicalPath("notExist");
    willReturn(new SftpClient.Attributes()).given(sftpClient).stat("/exist");
    willThrow(new SftpException(SftpConstants.SSH_FX_NO_SUCH_FILE, "notExist")).given(sftpClient).stat("/notExist");
    willThrow(new SshException(SshConstants.SSH_OPEN_CONNECT_FAILED, "Connection lost.")).given(sftpClient).stat(and(not(eq("/exist")), not(eq("/notExist"))));
    SftpSession sftpSession = new SftpSession(sftpClient);
    assertThat(sftpSession.exists("exist")).isTrue();
    assertThat(sftpSession.exists("notExist")).isFalse();
    assertThatExceptionOfType(UncheckedIOException.class).isThrownBy(() -> sftpSession.exists("foo"));
}

